<?php require_once 'functions.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){ $ids=$_POST['stock_id']??[];$qtys=$_POST['quantity']??[];$prices=$_POST['price']??[];try{db()->beginTransaction();foreach($ids as $k=>$id){$id=(int)$id;$qty=(int)($qtys[$k]??0);$price=(float)($prices[$k]??0);if($id<=0||$qty<=0||$price<0)continue;$q=db()->prepare('SELECT * FROM stocks WHERE id=? FOR UPDATE');$q->execute([$id]);$s=$q->fetch();if(!$s||$s['quantity']<$qty)throw new Exception('Not enough stock for '.($s['name']??'item'));db()->prepare('UPDATE stocks SET quantity=quantity-? WHERE id=?')->execute([$qty,$id]);db()->prepare('INSERT INTO billings(name,quantity,unit,price) VALUES(?,?,?,?)')->execute([$s['name'],$qty,$s['unit'],$price]);}db()->commit();flash('Billing successful and stock updated.');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash($e->getMessage(),'error');}redirect('billing.php');}$pageTitle='Billing';$all=stocks();$history=db()->query('SELECT * FROM billings ORDER BY date DESC LIMIT 100')->fetchAll();require 'partials/header.php'; ?><div class="billing-page"><div class="billing-container panel"><h2 class="section-title">Billing Section</h2><form method="post"><div id="billRows"><div class="input-grid form-grid bill-row"><select name="stock_id[]" required><option value="">Select Item</option><?php foreach($all as $s):?><option value="<?=$s['id']?>"><?=e($s['name'])?> (<?=e($s['quantity'])?> <?=e($s['unit'])?>)</option><?php endforeach;?></select><input type="number" name="quantity[]" min="1" placeholder="Quantity" required><input type="number" name="price[]" min="0" step="0.01" placeholder="Price per unit" required></div></div><button type="button" onclick="addRow()">+ Add item</button> <button type="submit">Confirm Bill</button></form></div><div class="panel"><h2>Billing History</h2><div class="table-wrap"><table><thead><tr><th>Item</th><th>Quantity</th><th>Unit</th><th>Price</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['name'])?></td><td><?=e($h['quantity'])?></td><td><?=e($h['unit'])?></td><td>₹<?=number_format((float)$h['price'],2)?></td><td>₹<?=number_format((float)$h['quantity']*(float)$h['price'],2)?></td><td><?=e($h['date'])?></td></tr><?php endforeach;?></tbody></table></div></div></div><script>function addRow(){let r=document.querySelector('.bill-row').cloneNode(true);r.querySelectorAll('input').forEach(x=>x.value='');document.getElementById('billRows').appendChild(r)}</script><?php require 'partials/footer.php'; ?>